package typeutil

// Codec is an interface that provides Marshal and Unmarshal methods.
// It's used for deep cloning protobuf messages.
type Codec interface {
	Marshal() ([]byte, error)
	Unmarshal([]byte) error
}

// DeepClone performs a deep copy by marshaling the source via its Codec interface
// and unmarshaling into a newly allocated object created by the supplied factory.
// If src is nil or Marshal/Unmarshal fails, returns the zero value of T.
func DeepClone[T Codec](src T, factory func() T) T {
	if src == nil {
		return factory()
	}

	data, err := src.Marshal()
	if err != nil {
		return factory()
	}

	dst := factory()
	if err := dst.Unmarshal(data); err != nil {
		return factory()
	}

	return dst
}
