package main

import (
	"fmt"
	"github.com/pingcap/kvproto/pkg/metapb"
	"github.com/tikv/pd/pkg/typeutil"
)

func main() {
	// Test DeepClone with metapb.Peer
	peer := &metapb.Peer{
		Id:      1,
		StoreId: 100,
		Role:    metapb.PeerRole_Voter,
	}

	clonedPeer := typeutil.DeepClone(peer, func() *metapb.Peer {
		return &metapb.Peer{}
	})

	fmt.Printf("Original peer: %+v\n", peer)
	fmt.Printf("Cloned peer: %+v\n", clonedPeer)

	// Verify they're different objects
	if peer == clonedPeer {
		fmt.Println("ERROR: Same object!")
	} else {
		fmt.Println("SUCCESS: Different objects")
	}

	// Verify they have the same values
	if peer.Id == clonedPeer.Id && peer.StoreId == clonedPeer.StoreId && peer.Role == clonedPeer.Role {
		fmt.Println("SUCCESS: Values match")
	} else {
		fmt.Println("ERROR: Values don't match")
	}

	// Test with nil
	var nilPeer *metapb.Peer = nil
	clonedNilPeer := typeutil.DeepClone(nilPeer, func() *metapb.Peer {
		return &metapb.Peer{}
	})

	if clonedNilPeer != nil {
		fmt.Println("SUCCESS: Nil handled correctly")
	} else {
		fmt.Println("ERROR: Nil not handled correctly")
	}
}
EOF
